package com.aislide.studio.data.model

import kotlinx.serialization.Serializable

/**
 * A slide inside a presentation.
 *
 * A slide is composed of [SlideObject]s (text boxes, images, shapes, etc.).
 * Each object has absolute positioning (in percentage of slide size 0..1),
 * so the slide can be rendered at any resolution — HTML, SVG, or PPTX EMU.
 *
 * The slide also keeps its raw HTML representation, generated by the IA
 * from the JSON structure, and rendered via WebView in the app.
 */
@Serializable
data class Slide(
    val id: String,            // UUID generated client-side
    val index: Int,           // 0-based position in the presentation
    val layout: SlideLayout,
    val title: String = "",
    val subtitle: String = "",
    val objects: List<SlideObject> = emptyList(),
    val backgroundHex: String? = null,  // override palette bg if set
    val notesForSpeaker: String = "",
    val htmlContent: String = "",      // HTML rendered from the structure above
    val transition: SlideTransition = SlideTransition.NONE
)

@Serializable
enum class SlideLayout {
    TITLE,                // Big title slide (cover)
    TITLE_AND_BULLETS,    // Title + bullet list (most common)
    TITLE_AND_IMAGE,      // Title + image on right
    IMAGE_FULL,           // Full-bleed image with title overlay
    TWO_COLUMNS,          // Title + 2 columns of content
    QUOTE,                // Big quote with attribution
    SECTION_DIVIDER,      // "Part 1: ..." divider
    DATA_TABLE,           // Title + table
    DATA_CHART,           // Title + chart placeholder
    CONCLUSION            // Final thank-you slide
}

@Serializable
enum class SlideTransition {
    NONE, FADE, SLIDE, ZOOM
}
